export default {"file":"notices.html","title":"Schoolix Notices","htmlClass":"","bodyClass":"sx-admin-app sx-notices-app","body":"\n  <main class=\"page\" id=\"pageShell\">\n    <header class=\"topbar\">\n      <div>\n        <a class=\"crumb\" id=\"backLink\" href=\"#/admin-dashboard.html\"><i class=\"fa-solid fa-arrow-left\"></i> Back</a>\n        <h1>Notices</h1>\n        <p class=\"subtitle\">Publish school notices as text or PDF, choose the audience, and send an app alert instantly.</p>\n      </div>\n      <div class=\"role-pill\"><i class=\"fa-solid fa-user-shield\"></i><span id=\"roleLabel\">Loading...</span></div>\n    </header>\n\n    <section class=\"layout\">\n      <article class=\"panel composer-panel\">\n        <div class=\"panel-header\">\n          <h2 class=\"panel-title\">Create Notice</h2>\n          <i class=\"fa-solid fa-bullhorn\" aria-hidden=\"true\"></i>\n        </div>\n        <div class=\"panel-body\">\n          <form class=\"form-grid\" id=\"noticeForm\">\n            <div>\n              <label for=\"audience\">Send to</label>\n              <select id=\"audience\" required>\n                <option value=\"all\">Everyone</option>\n                <option value=\"students\">All Students</option>\n                <option value=\"teachers\">All Teachers</option>\n                <option value=\"librarians\">All Librarians</option>\n                <option value=\"accountants\">All Accountants</option>\n              </select>\n            </div>\n            <div>\n              <label for=\"noticeTitle\">Notice title</label>\n              <input id=\"noticeTitle\" maxlength=\"120\" placeholder=\"Example: Unit test schedule\" required>\n            </div>\n            <div>\n              <label for=\"noticeMessage\">Notice message</label>\n              <textarea id=\"noticeMessage\" maxlength=\"2000\" placeholder=\"Write the notice details here...\"></textarea>\n            </div>\n            <div class=\"file-box\">\n              <label for=\"noticeFile\">Attach PDF or image</label>\n              <input id=\"noticeFile\" type=\"file\" accept=\"application/pdf,.pdf,image/png,image/jpeg,image/webp,image/gif\">\n              <p class=\"hint\">Optional PDF/image, up to 10 MB. Files are stored securely with the notice.</p>\n            </div>\n            <button class=\"btn btn-primary\" id=\"publishBtn\" type=\"submit\">\n              <i class=\"fa-solid fa-paper-plane\"></i>\n              Publish Notice\n            </button>\n          </form>\n        </div>\n      </article>\n\n      <article class=\"panel\">\n        <div class=\"panel-header\">\n          <h2 class=\"panel-title\">Notice Board</h2>\n          <button class=\"btn btn-light\" id=\"refreshBtn\" type=\"button\"><i class=\"fa-solid fa-rotate\"></i>Refresh</button>\n        </div>\n        <div class=\"panel-body\">\n          <div class=\"notice-list\" id=\"noticeList\">\n            <div class=\"empty\">Loading notices...</div>\n          </div>\n        </div>\n      </article>\n    </section>\n  </main>\n\n  <div class=\"toast\" id=\"toast\" role=\"status\" aria-live=\"polite\"></div>\n\n  <script type=\"module\">\n    import { initializeApp, getApps } from \"./firebase-compat.js\";\n    import { getAuth, onAuthStateChanged } from \"./firebase-compat.js\";\n    import { getFirestore, doc, getDoc, collection, addDoc, getDocs, query, orderBy, limit, serverTimestamp, updateDoc } from \"./firebase-compat.js\";\n\n    const firebaseConfig = {\n      apiKey: \"AIzaSyAomGwef93HFT9Xyx7SVW95FPw_IcIAICE\",\n      authDomain: \"schoolix-48107.firebaseapp.com\",\n      projectId: \"schoolix-48107\"\n    };\n\n    const SEND_URL = \"https://ezkmeedcqetztkeppxil.supabase.co/functions/v1/send-app-notification\";\n    const ATTACHMENT_URL = \"https://ezkmeedcqetztkeppxil.supabase.co/functions/v1/upload-notice-attachment\";\n    const SUPABASE_ANON_KEY = \"eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6ImV6a21lZWRjcWV0enRrZXBweGlsIiwicm9sZSI6ImFub24iLCJpYXQiOjE3NzgxMjk5NjAsImV4cCI6MjA5MzcwNTk2MH0.1davJ_NYkFhHToUtcFBR0kA6dk0-cOkaIbK2SCObkQg\";\n    const PDF_LIMIT = 10 * 1024 * 1024;\n\n    const app = getApps().length ? getApps()[0] : initializeApp(firebaseConfig);\n    const auth = getAuth(app);\n    const db = getFirestore(app);\n\n    const $ = (id) => document.getElementById(id);\n    const pageShell = $(\"pageShell\");\n    const noticeForm = $(\"noticeForm\");\n    const publishBtn = $(\"publishBtn\");\n    const noticeList = $(\"noticeList\");\n    const roleLabel = $(\"roleLabel\");\n    const backLink = $(\"backLink\");\n    let currentUser = null;\n    let currentProfile = null;\n    let schoolId = \"\";\n    let role = \"\";\n    let latestNotices = [];\n\n    function toast(message, type = \"\") {\n      const node = $(\"toast\");\n      node.textContent = message;\n      node.className = `toast show ${type}`;\n      window.clearTimeout(toast.timer);\n      toast.timer = window.setTimeout(() => {\n        node.className = \"toast\";\n      }, 4200);\n    }\n\n    function escapeHtml(value) {\n      return String(value || \"\")\n        .replace(/&/g, \"&amp;\")\n        .replace(/</g, \"&lt;\")\n        .replace(/>/g, \"&gt;\")\n        .replace(/\"/g, \"&quot;\")\n        .replace(/'/g, \"&#039;\");\n    }\n\n    function normalizeRole(value) {\n      const clean = String(value || \"\").trim().toLowerCase();\n      if (clean === \"teacher\" || clean === \"teachers\") return \"teacher\";\n      if (clean === \"student\" || clean === \"students\" || clean === \"parent\") return \"student\";\n      if (clean === \"superadmin\" || clean === \"super admin\") return \"superadmin\";\n      return clean || \"user\";\n    }\n\n    function audienceLabel(value) {\n      if (value === \"teachers\") return \"Teachers\";\n      if (value === \"students\") return \"Students\";\n      if (value === \"librarians\") return \"Librarians\";\n      if (value === \"accountants\") return \"Accountants\";\n      return \"Everyone\";\n    }\n\n    function audienceAllowed(value) {\n      if (role === \"admin\" || role === \"superadmin\") return true;\n      if (role === \"teacher\") return value === \"all\" || value === \"teachers\";\n      if (role === \"librarian\") return value === \"all\" || value === \"librarians\";\n      if (role === \"accountant\") return value === \"all\" || value === \"accountants\";\n      return value === \"all\" || value === \"students\";\n    }\n\n    function formatDate(value) {\n      const raw = value?.toDate ? value.toDate() : value ? new Date(value) : null;\n      if (!raw || Number.isNaN(raw.getTime())) return \"Just now\";\n      return raw.toLocaleString(\"en-IN\", { dateStyle: \"medium\", timeStyle: \"short\" });\n    }\n\n    function getStudentSession() {\n      try { return JSON.parse(localStorage.getItem(\"schoolixStudentSession\") || \"null\"); } catch { return null; }\n    }\n\n    async function getProfile(uid) {\n      const snap = await getDoc(doc(db, \"users\", uid));\n      return snap.exists() ? { id: snap.id, ...snap.data() } : null;\n    }\n\n    function resolveSchoolId(profile, user) {\n      return String(\n        profile?.schoolId ||\n        profile?.adminId ||\n        profile?.adminUID ||\n        profile?.adminUid ||\n        profile?.schoolUID ||\n        profile?.schoolUid ||\n        (normalizeRole(profile?.role) === \"admin\" ? user?.uid : \"\") ||\n        profile?.id ||\n        \"\"\n      ).trim();\n    }\n\n    function configureForRole() {\n      const canCompose = role === \"admin\" || role === \"superadmin\";\n      pageShell.classList.toggle(\"composer-hidden\", !canCompose);\n      pageShell.classList.toggle(\"can-manage-notices\", canCompose);\n      roleLabel.textContent = role === \"teacher\" ? \"Teacher\" : role === \"student\" ? \"Student\" : \"Admin\";\n      backLink.href = role === \"teacher\" ? \"#/teacher-dashboard.html\" : role === \"student\" ? \"#/student-dashboard.html\" : \"#/admin-dashboard.html\";\n      document.title = canCompose ? \"Schoolix Notices\" : \"Schoolix Notice Board\";\n    }\n\n    function getAttachmentKind(file) {\n      if (!file) return \"\";\n      if ([\"image/png\", \"image/jpeg\", \"image/webp\", \"image/gif\"].includes(file.type) || /\\.(png|jpe?g|webp|gif)$/i.test(file.name)) return \"image\";\n      if (file.type === \"application/pdf\" || file.name.toLowerCase().endsWith(\".pdf\")) return \"pdf\";\n      return \"\";\n    }\n\n    async function uploadAttachment(file) {\n      if (!file) return {};\n      if (file.size > PDF_LIMIT) throw new Error(\"Attachment 10 MB se chhoti honi chahiye.\");\n      const attachmentType = getAttachmentKind(file);\n      if (!attachmentType) throw new Error(\"Sirf PDF ya image file upload kar sakte hain.\");\n      if (!currentUser) throw new Error(\"Attachment upload ke liye admin login required hai.\");\n\n      const idToken = await currentUser.getIdToken(true);\n      const formData = new FormData();\n      formData.append(\"file\", file, file.name);\n      formData.append(\"schoolId\", schoolId);\n      const response = await fetch(ATTACHMENT_URL, {\n        method: \"POST\",\n        headers: {\n          \"Authorization\": `Bearer ${SUPABASE_ANON_KEY}`,\n          \"apikey\": SUPABASE_ANON_KEY,\n          \"x-firebase-token\": idToken\n        },\n        body: formData\n      });\n      const payload = await response.json().catch(() => ({}));\n      if (!response.ok || !payload.attachmentUrl) {\n        throw new Error(payload.error || \"Attachment upload nahi ho paya.\");\n      }\n      return {\n        attachmentUrl: payload.attachmentUrl,\n        attachmentName: payload.attachmentName || file.name,\n        attachmentType: payload.attachmentType || attachmentType,\n        attachmentPublicId: payload.storagePath || \"\",\n        attachmentStoragePath: payload.storagePath || \"\",\n        pdfUrl: attachmentType === \"pdf\" ? payload.attachmentUrl : \"\",\n        pdfName: attachmentType === \"pdf\" ? (payload.attachmentName || file.name) : \"\",\n        pdfPublicId: attachmentType === \"pdf\" ? (payload.storagePath || \"\") : \"\"\n      };\n    }\n\n    async function deleteUploadedAttachment(storagePath) {\n      if (!storagePath || !currentUser) return;\n      const idToken = await currentUser.getIdToken();\n      await fetch(ATTACHMENT_URL, {\n        method: \"POST\",\n        headers: {\n          \"Content-Type\": \"application/json\",\n          \"Authorization\": `Bearer ${SUPABASE_ANON_KEY}`,\n          \"apikey\": SUPABASE_ANON_KEY,\n          \"x-firebase-token\": idToken\n        },\n        body: JSON.stringify({ action: \"delete\", path: storagePath })\n      });\n    }\n\n    async function sendNoticeNotification(title, message, audience) {\n      const idToken = await currentUser.getIdToken(true);\n      if (![\"all\", \"students\", \"teachers\"].includes(audience)) {\n        return { skipped: true };\n      }\n      const response = await fetch(SEND_URL, {\n        method: \"POST\",\n        headers: {\n          \"Content-Type\": \"application/json\",\n          \"Authorization\": `Bearer ${SUPABASE_ANON_KEY}`,\n          \"apikey\": SUPABASE_ANON_KEY,\n          \"x-firebase-token\": idToken\n        },\n        body: JSON.stringify({\n          title: \"New Notice\",\n          message: title || message || \"A new notice has been published.\",\n          audience\n        })\n      });\n      const payload = await response.json().catch(() => ({}));\n      if (!response.ok || payload.success === false) {\n        throw new Error(payload.error || payload.message || \"Notification send nahi ho payi.\");\n      }\n    }\n\n    function renderNotices(items) {\n      latestNotices = items;\n      if (!items.length) {\n        noticeList.innerHTML = '<div class=\"empty\">No notices yet.</div>';\n        return;\n      }\n\n      const canManage = role === \"admin\" || role === \"superadmin\";\n      noticeList.innerHTML = items.map((notice) => {\n        const title = escapeHtml(notice.title);\n        const message = escapeHtml(notice.message);\n        const attachmentUrl = notice.attachmentUrl || notice.pdfUrl || \"\";\n        const attachmentName = notice.attachmentName || notice.pdfName || \"Open attachment\";\n        const attachmentType = notice.attachmentType || (String(attachmentName).toLowerCase().match(/\\.(png|jpe?g|webp|gif)$/) ? \"image\" : \"pdf\");\n        const pdfLink = attachmentUrl\n          ? `<a class=\"pdf-link\" href=\"${escapeHtml(attachmentUrl)}\" target=\"_blank\" rel=\"noopener\"><i class=\"fa-solid ${attachmentType === \"image\" ? \"fa-image\" : \"fa-file-pdf\"}\"></i>${escapeHtml(attachmentName)}</a>`\n          : \"\";\n        return `\n          <article class=\"notice-card\">\n            <div class=\"notice-head\">\n              <h3 class=\"notice-title\">${title}</h3>\n              <div class=\"notice-actions\">\n                <span class=\"badge\"><i class=\"fa-solid fa-users\"></i>${audienceLabel(notice.audience)}</span>\n                ${canManage ? `<button class=\"btn btn-danger notice-delete-btn\" type=\"button\" data-notice-id=\"${escapeHtml(notice.id)}\" title=\"Delete notice\"><i class=\"fa-solid fa-trash\"></i>Delete</button>` : \"\"}\n              </div>\n            </div>\n            ${message ? `<p class=\"notice-message\">${message}</p>` : \"\"}\n            <div class=\"notice-meta\">\n              <span><i class=\"fa-regular fa-clock\"></i> ${formatDate(notice.createdAt)}</span>\n              ${pdfLink}\n            </div>\n          </article>\n        `;\n      }).join(\"\");\n    }\n\n    async function loadNotices() {\n      if (!schoolId) return;\n      noticeList.innerHTML = '<div class=\"empty\">Loading notices...</div>';\n      const snap = await getDocs(query(collection(db, \"schools\", schoolId, \"notices\"), orderBy(\"createdAt\", \"desc\"), limit(80)));\n      const items = snap.docs.map((docSnap) => ({ id: docSnap.id, ...docSnap.data() }))\n        .filter((notice) => notice.status !== \"deleted\")\n        .filter((notice) => audienceAllowed(notice.audience || \"all\"));\n      renderNotices(items);\n    }\n\n    async function deleteNotice(noticeId) {\n      if (!(role === \"admin\" || role === \"superadmin\")) return;\n      const notice = latestNotices.find((item) => item.id === noticeId);\n      if (!notice) return toast(\"Notice nahi mila. Refresh karke try karo.\", \"error\");\n      const ok = window.confirm(`Delete notice \"${notice.title || \"Untitled\"}\"?`);\n      if (!ok) return;\n\n      const button = noticeList.querySelector(`[data-notice-id=\"${CSS.escape(noticeId)}\"]`);\n      if (button) {\n        button.disabled = true;\n        button.innerHTML = '<i class=\"fa-solid fa-spinner fa-spin\"></i>Deleting...';\n      }\n\n      await updateDoc(doc(db, \"schools\", schoolId, \"notices\", noticeId), {\n        status: \"deleted\",\n        deletedAt: serverTimestamp(),\n        deletedBy: currentUser?.uid || currentProfile?.id || \"\",\n        deletedByEmail: currentUser?.email || currentProfile?.email || \"\"\n      });\n\n      const storagePath = notice.attachmentStoragePath || notice.attachmentPublicId || notice.pdfPublicId || \"\";\n      if (storagePath) {\n        await deleteUploadedAttachment(storagePath).catch((cleanupError) => console.warn(\"Attachment cleanup failed\", cleanupError));\n      }\n\n      toast(\"Notice delete ho gaya.\", \"success\");\n      await loadNotices();\n    }\n\n    async function publishNotice(event) {\n      event.preventDefault();\n      if (!(role === \"admin\" || role === \"superadmin\")) return;\n      const title = $(\"noticeTitle\").value.trim();\n      const message = $(\"noticeMessage\").value.trim();\n      const audience = $(\"audience\").value;\n      const file = $(\"noticeFile\").files[0] || null;\n      if (!title) return toast(\"Notice title required hai.\", \"error\");\n      if (!message && !file) return toast(\"Message likho ya PDF attach karo.\", \"error\");\n\n      publishBtn.disabled = true;\n      publishBtn.innerHTML = file\n        ? '<i class=\"fa-solid fa-spinner fa-spin\"></i>Uploading attachment...'\n        : '<i class=\"fa-solid fa-spinner fa-spin\"></i>Publishing...';\n      let upload = {};\n      try {\n        upload = await uploadAttachment(file);\n        publishBtn.innerHTML = '<i class=\"fa-solid fa-spinner fa-spin\"></i>Saving notice...';\n        await addDoc(collection(db, \"schools\", schoolId, \"notices\"), {\n          schoolId,\n          title,\n          message,\n          audience,\n          recipientRoles: audience === \"all\" ? [\"students\", \"teachers\", \"librarians\", \"accountants\"] : [audience],\n          attachmentUrl: upload.attachmentUrl || \"\",\n          attachmentName: upload.attachmentName || \"\",\n          attachmentType: upload.attachmentType || \"\",\n          attachmentPublicId: upload.attachmentPublicId || \"\",\n          attachmentStoragePath: upload.attachmentStoragePath || \"\",\n          pdfUrl: upload.pdfUrl || \"\",\n          pdfName: upload.pdfName || \"\",\n          pdfPublicId: upload.pdfPublicId || \"\",\n          createdAt: serverTimestamp(),\n          createdBy: currentUser?.uid || currentProfile?.id || \"\",\n          createdByEmail: currentUser?.email || currentProfile?.email || \"\",\n          status: \"published\"\n        });\n\n        try {\n          const notificationResult = await sendNoticeNotification(title, message, audience);\n          toast(notificationResult?.skipped ? \"Notice publish ho gaya.\" : \"Notice publish ho gaya aur app notification bhej di.\", \"success\");\n        } catch (notifyError) {\n          console.warn(\"Notice saved but notification failed\", notifyError);\n          toast(`Notice saved, lekin notification nahi gayi: ${notifyError.message}`, \"error\");\n        }\n\n        noticeForm.reset();\n        await loadNotices();\n      } catch (error) {\n        console.error(error);\n        if (upload.attachmentStoragePath) {\n          await deleteUploadedAttachment(upload.attachmentStoragePath).catch((cleanupError) => console.warn(\"Attachment cleanup failed\", cleanupError));\n        }\n        toast(error.message || \"Notice publish nahi ho paya.\", \"error\");\n      } finally {\n        publishBtn.disabled = false;\n        publishBtn.innerHTML = '<i class=\"fa-solid fa-paper-plane\"></i>Publish Notice';\n      }\n    }\n\n    async function bootWithProfile(user, profile) {\n      currentUser = user;\n      currentProfile = profile || {};\n      role = normalizeRole(currentProfile.role || currentProfile.loginAs);\n      schoolId = resolveSchoolId(currentProfile, user);\n      if (!schoolId) {\n        noticeList.innerHTML = '<div class=\"empty\">School profile nahi mila. Please login again.</div>';\n        return;\n      }\n      configureForRole();\n      await loadNotices();\n    }\n\n    noticeForm.addEventListener(\"submit\", publishNotice);\n    $(\"refreshBtn\").addEventListener(\"click\", () => loadNotices().catch((error) => toast(error.message, \"error\")));\n    noticeList.addEventListener(\"click\", (event) => {\n      const button = event.target.closest(\".notice-delete-btn\");\n      if (!button) return;\n      deleteNotice(button.dataset.noticeId).catch((error) => {\n        console.error(error);\n        toast(error.message || \"Notice delete nahi ho paya.\", \"error\");\n        loadNotices().catch((loadError) => console.warn(\"Notice reload failed\", loadError));\n      });\n    });\n\n    onAuthStateChanged(auth, async (user) => {\n      if (user) {\n        try {\n          const profile = await getProfile(user.uid);\n          await bootWithProfile(user, profile || { id: user.uid, role: \"admin\" });\n        } catch (error) {\n          console.error(error);\n          toast(\"Profile load nahi ho paya.\", \"error\");\n        }\n        return;\n      }\n\n      const session = getStudentSession();\n      if (session?.schoolId || session?.adminId) {\n        await bootWithProfile(null, { ...session, role: session.role || session.loginAs || \"student\" });\n        return;\n      }\n\n      window.location.replace(\"#/index.html\");\n    });\n  </script>\n  <script type=\"module\" src=\"access-control.js\"></script>\n  <script src=\"schoolix-polish.js\"></script>\n  <script src=\"admin-shell.js?v=navbar-20260721\" defer></script>\n","styles":[{"tag":"link","attributes":{"rel":"stylesheet","href":"schoolix-polish.css"},"text":"\n  <link rel=\"stylesheet\" href=\"admin-shell.css?v=navbar-20260721\">\n  <link rel=\"stylesheet\" href=\"https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.5.0/css/all.min.css\">\n  <style>\n    :root {\n      --bg: #f6f8fb;\n      --panel: #ffffff;\n      --text: #172033;\n      --muted: #667085;\n      --line: #d9e2ef;\n      --primary: #2563eb;\n      --primary-soft: #eaf1ff;\n      --success: #0f9f6e;\n      --danger: #dc2626;\n      --shadow: 0 18px 46px rgba(22, 33, 54, 0.11);\n    }\n\n    * { box-sizing: border-box; }\n\n    body {\n      margin: 0;\n      font-family: Inter, \"Segoe UI\", Arial, sans-serif;\n      background: var(--bg);\n      color: var(--text);\n      min-height: 100vh;\n    }\n\n    .page {\n      width: min(1180px, calc(100% - 32px));\n      margin: 0 auto;\n      padding: 24px 0 38px;\n    }\n\n    .topbar {\n      display: flex;\n      align-items: center;\n      justify-content: space-between;\n      gap: 16px;\n      margin-bottom: 22px;\n    }\n\n    .crumb {\n      display: inline-flex;\n      align-items: center;\n      gap: 8px;\n      color: var(--muted);\n      text-decoration: none;\n      font-size: 14px;\n      font-weight: 700;\n      margin-bottom: 10px;\n    }\n\n    h1 {\n      margin: 0;\n      font-size: clamp(26px, 4vw, 38px);\n      line-height: 1.08;\n      letter-spacing: 0;\n    }\n\n    .subtitle {\n      margin: 8px 0 0;\n      color: var(--muted);\n      max-width: 680px;\n      line-height: 1.55;\n    }\n\n    .role-pill {\n      display: inline-flex;\n      align-items: center;\n      gap: 8px;\n      border: 1px solid var(--line);\n      background: var(--panel);\n      border-radius: 999px;\n      padding: 10px 14px;\n      color: var(--muted);\n      font-weight: 800;\n      white-space: nowrap;\n      box-shadow: 0 8px 22px rgba(15, 23, 42, 0.06);\n    }\n\n    .layout {\n      display: grid;\n      grid-template-columns: minmax(320px, 420px) minmax(0, 1fr);\n      gap: 18px;\n      align-items: start;\n    }\n\n    .panel {\n      background: var(--panel);\n      border: 1px solid var(--line);\n      border-radius: 18px;\n      box-shadow: var(--shadow);\n      overflow: hidden;\n    }\n\n    .panel-header {\n      padding: 18px 20px;\n      border-bottom: 1px solid var(--line);\n      display: flex;\n      align-items: center;\n      justify-content: space-between;\n      gap: 14px;\n    }\n\n    .panel-title {\n      margin: 0;\n      font-size: 18px;\n      font-weight: 900;\n    }\n\n    .panel-body { padding: 20px; }\n\n    .form-grid {\n      display: grid;\n      gap: 15px;\n    }\n\n    label {\n      display: block;\n      font-size: 13px;\n      color: #475467;\n      font-weight: 800;\n      margin-bottom: 7px;\n    }\n\n    input,\n    select,\n    textarea {\n      width: 100%;\n      border: 1px solid #cfd8e6;\n      border-radius: 12px;\n      padding: 12px 13px;\n      font: inherit;\n      color: var(--text);\n      background: #fff;\n      outline: none;\n      transition: border-color .2s ease, box-shadow .2s ease;\n    }\n\n    textarea {\n      resize: vertical;\n      min-height: 132px;\n      line-height: 1.45;\n    }\n\n    input:focus,\n    select:focus,\n    textarea:focus {\n      border-color: var(--primary);\n      box-shadow: 0 0 0 4px rgba(37, 99, 235, 0.12);\n    }\n\n    .file-box {\n      border: 1px dashed #aebbd0;\n      background: #f8fbff;\n      border-radius: 14px;\n      padding: 14px;\n    }\n\n    .file-box input { padding: 10px; background: #fff; }\n\n    .hint {\n      margin: 7px 0 0;\n      color: var(--muted);\n      font-size: 12px;\n      line-height: 1.4;\n    }\n\n    .btn {\n      border: 0;\n      border-radius: 12px;\n      padding: 12px 16px;\n      font: inherit;\n      font-weight: 900;\n      cursor: pointer;\n      display: inline-flex;\n      align-items: center;\n      justify-content: center;\n      gap: 9px;\n      min-height: 46px;\n      transition: transform .15s ease, box-shadow .15s ease, opacity .15s ease;\n    }\n\n    .btn:hover { transform: translateY(-1px); }\n    .btn:disabled { opacity: .65; cursor: not-allowed; transform: none; }\n\n    .btn-primary {\n      color: #fff;\n      background: linear-gradient(135deg, #2563eb, #0f9f6e);\n      box-shadow: 0 12px 24px rgba(37, 99, 235, 0.24);\n    }\n\n    .btn-light {\n      color: var(--text);\n      background: #eef3f9;\n      text-decoration: none;\n    }\n\n    .btn-danger {\n      color: #b42318;\n      background: #fff1f0;\n      border: 1px solid #ffd5d1;\n      min-height: 38px;\n      padding: 8px 11px;\n      box-shadow: none;\n    }\n\n    .notice-list {\n      display: grid;\n      gap: 14px;\n    }\n\n    .notice-card {\n      border: 1px solid var(--line);\n      border-radius: 16px;\n      padding: 16px;\n      background: #fff;\n    }\n\n    .notice-head {\n      display: flex;\n      align-items: flex-start;\n      justify-content: space-between;\n      gap: 12px;\n    }\n\n    .notice-title {\n      margin: 0;\n      font-size: 17px;\n      line-height: 1.25;\n      font-weight: 900;\n    }\n\n    .notice-actions {\n      display: inline-flex;\n      align-items: center;\n      gap: 8px;\n      flex-wrap: wrap;\n      justify-content: flex-end;\n    }\n\n    .badge {\n      display: inline-flex;\n      align-items: center;\n      gap: 6px;\n      border-radius: 999px;\n      background: var(--primary-soft);\n      color: #1d4ed8;\n      padding: 6px 10px;\n      font-size: 12px;\n      font-weight: 900;\n      white-space: nowrap;\n    }\n\n    .notice-message {\n      margin: 10px 0 0;\n      color: #344054;\n      line-height: 1.55;\n      white-space: pre-wrap;\n    }\n\n    .notice-meta {\n      margin-top: 12px;\n      display: flex;\n      align-items: center;\n      justify-content: space-between;\n      flex-wrap: wrap;\n      gap: 10px;\n      color: var(--muted);\n      font-size: 13px;\n    }\n\n    .pdf-link {\n      display: inline-flex;\n      align-items: center;\n      gap: 8px;\n      color: #b42318;\n      background: #fff1f0;\n      border: 1px solid #ffd5d1;\n      border-radius: 10px;\n      padding: 8px 10px;\n      text-decoration: none;\n      font-weight: 900;\n    }\n\n    .empty {\n      text-align: center;\n      color: var(--muted);\n      padding: 42px 18px;\n      border: 1px dashed var(--line);\n      border-radius: 16px;\n      background: #fbfdff;\n    }\n\n    .toast {\n      position: fixed;\n      right: 18px;\n      bottom: 18px;\n      max-width: min(430px, calc(100% - 36px));\n      background: #172033;\n      color: #fff;\n      border-radius: 14px;\n      padding: 13px 15px;\n      box-shadow: 0 18px 38px rgba(15, 23, 42, 0.24);\n      display: none;\n      z-index: 20;\n      font-weight: 800;\n    }\n\n    .toast.show { display: block; }\n    .toast.error { background: var(--danger); }\n    .toast.success { background: var(--success); }\n    .composer-hidden .composer-panel { display: none; }\n    .composer-hidden .layout { grid-template-columns: minmax(0, 1fr); }\n\n    body.sx-admin-shell-enabled.sx-notices-app .page {\n      padding-top: 0;\n    }\n\n    body.sx-admin-shell-enabled.sx-notices-app .topbar {\n      display: none;\n    }\n\n    @media (max-width: 820px) {\n      .page { width: min(100% - 22px, 1180px); padding-top: 16px; }\n      .topbar { align-items: flex-start; flex-direction: column; }\n      .layout { grid-template-columns: 1fr; }\n      .panel-header, .panel-body { padding: 16px; }\n      .notice-head { flex-direction: column; }\n    }\n  "}],"scripts":[{"attributes":{"type":"module"},"text":"\n    import { initializeApp, getApps } from \"./firebase-compat.js\";\n    import { getAuth, onAuthStateChanged } from \"./firebase-compat.js\";\n    import { getFirestore, doc, getDoc, collection, addDoc, getDocs, query, orderBy, limit, serverTimestamp, updateDoc } from \"./firebase-compat.js\";\n\n    const firebaseConfig = {\n      apiKey: \"AIzaSyAomGwef93HFT9Xyx7SVW95FPw_IcIAICE\",\n      authDomain: \"schoolix-48107.firebaseapp.com\",\n      projectId: \"schoolix-48107\"\n    };\n\n    const SEND_URL = \"https://ezkmeedcqetztkeppxil.supabase.co/functions/v1/send-app-notification\";\n    const ATTACHMENT_URL = \"https://ezkmeedcqetztkeppxil.supabase.co/functions/v1/upload-notice-attachment\";\n    const SUPABASE_ANON_KEY = \"eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6ImV6a21lZWRjcWV0enRrZXBweGlsIiwicm9sZSI6ImFub24iLCJpYXQiOjE3NzgxMjk5NjAsImV4cCI6MjA5MzcwNTk2MH0.1davJ_NYkFhHToUtcFBR0kA6dk0-cOkaIbK2SCObkQg\";\n    const PDF_LIMIT = 10 * 1024 * 1024;\n\n    const app = getApps().length ? getApps()[0] : initializeApp(firebaseConfig);\n    const auth = getAuth(app);\n    const db = getFirestore(app);\n\n    const $ = (id) => document.getElementById(id);\n    const pageShell = $(\"pageShell\");\n    const noticeForm = $(\"noticeForm\");\n    const publishBtn = $(\"publishBtn\");\n    const noticeList = $(\"noticeList\");\n    const roleLabel = $(\"roleLabel\");\n    const backLink = $(\"backLink\");\n    let currentUser = null;\n    let currentProfile = null;\n    let schoolId = \"\";\n    let role = \"\";\n    let latestNotices = [];\n\n    function toast(message, type = \"\") {\n      const node = $(\"toast\");\n      node.textContent = message;\n      node.className = `toast show ${type}`;\n      window.clearTimeout(toast.timer);\n      toast.timer = window.setTimeout(() => {\n        node.className = \"toast\";\n      }, 4200);\n    }\n\n    function escapeHtml(value) {\n      return String(value || \"\")\n        .replace(/&/g, \"&amp;\")\n        .replace(/</g, \"&lt;\")\n        .replace(/>/g, \"&gt;\")\n        .replace(/\"/g, \"&quot;\")\n        .replace(/'/g, \"&#039;\");\n    }\n\n    function normalizeRole(value) {\n      const clean = String(value || \"\").trim().toLowerCase();\n      if (clean === \"teacher\" || clean === \"teachers\") return \"teacher\";\n      if (clean === \"student\" || clean === \"students\" || clean === \"parent\") return \"student\";\n      if (clean === \"superadmin\" || clean === \"super admin\") return \"superadmin\";\n      return clean || \"user\";\n    }\n\n    function audienceLabel(value) {\n      if (value === \"teachers\") return \"Teachers\";\n      if (value === \"students\") return \"Students\";\n      if (value === \"librarians\") return \"Librarians\";\n      if (value === \"accountants\") return \"Accountants\";\n      return \"Everyone\";\n    }\n\n    function audienceAllowed(value) {\n      if (role === \"admin\" || role === \"superadmin\") return true;\n      if (role === \"teacher\") return value === \"all\" || value === \"teachers\";\n      if (role === \"librarian\") return value === \"all\" || value === \"librarians\";\n      if (role === \"accountant\") return value === \"all\" || value === \"accountants\";\n      return value === \"all\" || value === \"students\";\n    }\n\n    function formatDate(value) {\n      const raw = value?.toDate ? value.toDate() : value ? new Date(value) : null;\n      if (!raw || Number.isNaN(raw.getTime())) return \"Just now\";\n      return raw.toLocaleString(\"en-IN\", { dateStyle: \"medium\", timeStyle: \"short\" });\n    }\n\n    function getStudentSession() {\n      try { return JSON.parse(localStorage.getItem(\"schoolixStudentSession\") || \"null\"); } catch { return null; }\n    }\n\n    async function getProfile(uid) {\n      const snap = await getDoc(doc(db, \"users\", uid));\n      return snap.exists() ? { id: snap.id, ...snap.data() } : null;\n    }\n\n    function resolveSchoolId(profile, user) {\n      return String(\n        profile?.schoolId ||\n        profile?.adminId ||\n        profile?.adminUID ||\n        profile?.adminUid ||\n        profile?.schoolUID ||\n        profile?.schoolUid ||\n        (normalizeRole(profile?.role) === \"admin\" ? user?.uid : \"\") ||\n        profile?.id ||\n        \"\"\n      ).trim();\n    }\n\n    function configureForRole() {\n      const canCompose = role === \"admin\" || role === \"superadmin\";\n      pageShell.classList.toggle(\"composer-hidden\", !canCompose);\n      pageShell.classList.toggle(\"can-manage-notices\", canCompose);\n      roleLabel.textContent = role === \"teacher\" ? \"Teacher\" : role === \"student\" ? \"Student\" : \"Admin\";\n      backLink.href = role === \"teacher\" ? \"#/teacher-dashboard.html\" : role === \"student\" ? \"#/student-dashboard.html\" : \"#/admin-dashboard.html\";\n      document.title = canCompose ? \"Schoolix Notices\" : \"Schoolix Notice Board\";\n    }\n\n    function getAttachmentKind(file) {\n      if (!file) return \"\";\n      if ([\"image/png\", \"image/jpeg\", \"image/webp\", \"image/gif\"].includes(file.type) || /\\.(png|jpe?g|webp|gif)$/i.test(file.name)) return \"image\";\n      if (file.type === \"application/pdf\" || file.name.toLowerCase().endsWith(\".pdf\")) return \"pdf\";\n      return \"\";\n    }\n\n    async function uploadAttachment(file) {\n      if (!file) return {};\n      if (file.size > PDF_LIMIT) throw new Error(\"Attachment 10 MB se chhoti honi chahiye.\");\n      const attachmentType = getAttachmentKind(file);\n      if (!attachmentType) throw new Error(\"Sirf PDF ya image file upload kar sakte hain.\");\n      if (!currentUser) throw new Error(\"Attachment upload ke liye admin login required hai.\");\n\n      const idToken = await currentUser.getIdToken(true);\n      const formData = new FormData();\n      formData.append(\"file\", file, file.name);\n      formData.append(\"schoolId\", schoolId);\n      const response = await fetch(ATTACHMENT_URL, {\n        method: \"POST\",\n        headers: {\n          \"Authorization\": `Bearer ${SUPABASE_ANON_KEY}`,\n          \"apikey\": SUPABASE_ANON_KEY,\n          \"x-firebase-token\": idToken\n        },\n        body: formData\n      });\n      const payload = await response.json().catch(() => ({}));\n      if (!response.ok || !payload.attachmentUrl) {\n        throw new Error(payload.error || \"Attachment upload nahi ho paya.\");\n      }\n      return {\n        attachmentUrl: payload.attachmentUrl,\n        attachmentName: payload.attachmentName || file.name,\n        attachmentType: payload.attachmentType || attachmentType,\n        attachmentPublicId: payload.storagePath || \"\",\n        attachmentStoragePath: payload.storagePath || \"\",\n        pdfUrl: attachmentType === \"pdf\" ? payload.attachmentUrl : \"\",\n        pdfName: attachmentType === \"pdf\" ? (payload.attachmentName || file.name) : \"\",\n        pdfPublicId: attachmentType === \"pdf\" ? (payload.storagePath || \"\") : \"\"\n      };\n    }\n\n    async function deleteUploadedAttachment(storagePath) {\n      if (!storagePath || !currentUser) return;\n      const idToken = await currentUser.getIdToken();\n      await fetch(ATTACHMENT_URL, {\n        method: \"POST\",\n        headers: {\n          \"Content-Type\": \"application/json\",\n          \"Authorization\": `Bearer ${SUPABASE_ANON_KEY}`,\n          \"apikey\": SUPABASE_ANON_KEY,\n          \"x-firebase-token\": idToken\n        },\n        body: JSON.stringify({ action: \"delete\", path: storagePath })\n      });\n    }\n\n    async function sendNoticeNotification(title, message, audience) {\n      const idToken = await currentUser.getIdToken(true);\n      if (![\"all\", \"students\", \"teachers\"].includes(audience)) {\n        return { skipped: true };\n      }\n      const response = await fetch(SEND_URL, {\n        method: \"POST\",\n        headers: {\n          \"Content-Type\": \"application/json\",\n          \"Authorization\": `Bearer ${SUPABASE_ANON_KEY}`,\n          \"apikey\": SUPABASE_ANON_KEY,\n          \"x-firebase-token\": idToken\n        },\n        body: JSON.stringify({\n          title: \"New Notice\",\n          message: title || message || \"A new notice has been published.\",\n          audience\n        })\n      });\n      const payload = await response.json().catch(() => ({}));\n      if (!response.ok || payload.success === false) {\n        throw new Error(payload.error || payload.message || \"Notification send nahi ho payi.\");\n      }\n    }\n\n    function renderNotices(items) {\n      latestNotices = items;\n      if (!items.length) {\n        noticeList.innerHTML = '<div class=\"empty\">No notices yet.</div>';\n        return;\n      }\n\n      const canManage = role === \"admin\" || role === \"superadmin\";\n      noticeList.innerHTML = items.map((notice) => {\n        const title = escapeHtml(notice.title);\n        const message = escapeHtml(notice.message);\n        const attachmentUrl = notice.attachmentUrl || notice.pdfUrl || \"\";\n        const attachmentName = notice.attachmentName || notice.pdfName || \"Open attachment\";\n        const attachmentType = notice.attachmentType || (String(attachmentName).toLowerCase().match(/\\.(png|jpe?g|webp|gif)$/) ? \"image\" : \"pdf\");\n        const pdfLink = attachmentUrl\n          ? `<a class=\"pdf-link\" href=\"${escapeHtml(attachmentUrl)}\" target=\"_blank\" rel=\"noopener\"><i class=\"fa-solid ${attachmentType === \"image\" ? \"fa-image\" : \"fa-file-pdf\"}\"></i>${escapeHtml(attachmentName)}</a>`\n          : \"\";\n        return `\n          <article class=\"notice-card\">\n            <div class=\"notice-head\">\n              <h3 class=\"notice-title\">${title}</h3>\n              <div class=\"notice-actions\">\n                <span class=\"badge\"><i class=\"fa-solid fa-users\"></i>${audienceLabel(notice.audience)}</span>\n                ${canManage ? `<button class=\"btn btn-danger notice-delete-btn\" type=\"button\" data-notice-id=\"${escapeHtml(notice.id)}\" title=\"Delete notice\"><i class=\"fa-solid fa-trash\"></i>Delete</button>` : \"\"}\n              </div>\n            </div>\n            ${message ? `<p class=\"notice-message\">${message}</p>` : \"\"}\n            <div class=\"notice-meta\">\n              <span><i class=\"fa-regular fa-clock\"></i> ${formatDate(notice.createdAt)}</span>\n              ${pdfLink}\n            </div>\n          </article>\n        `;\n      }).join(\"\");\n    }\n\n    async function loadNotices() {\n      if (!schoolId) return;\n      noticeList.innerHTML = '<div class=\"empty\">Loading notices...</div>';\n      const snap = await getDocs(query(collection(db, \"schools\", schoolId, \"notices\"), orderBy(\"createdAt\", \"desc\"), limit(80)));\n      const items = snap.docs.map((docSnap) => ({ id: docSnap.id, ...docSnap.data() }))\n        .filter((notice) => notice.status !== \"deleted\")\n        .filter((notice) => audienceAllowed(notice.audience || \"all\"));\n      renderNotices(items);\n    }\n\n    async function deleteNotice(noticeId) {\n      if (!(role === \"admin\" || role === \"superadmin\")) return;\n      const notice = latestNotices.find((item) => item.id === noticeId);\n      if (!notice) return toast(\"Notice nahi mila. Refresh karke try karo.\", \"error\");\n      const ok = window.confirm(`Delete notice \"${notice.title || \"Untitled\"}\"?`);\n      if (!ok) return;\n\n      const button = noticeList.querySelector(`[data-notice-id=\"${CSS.escape(noticeId)}\"]`);\n      if (button) {\n        button.disabled = true;\n        button.innerHTML = '<i class=\"fa-solid fa-spinner fa-spin\"></i>Deleting...';\n      }\n\n      await updateDoc(doc(db, \"schools\", schoolId, \"notices\", noticeId), {\n        status: \"deleted\",\n        deletedAt: serverTimestamp(),\n        deletedBy: currentUser?.uid || currentProfile?.id || \"\",\n        deletedByEmail: currentUser?.email || currentProfile?.email || \"\"\n      });\n\n      const storagePath = notice.attachmentStoragePath || notice.attachmentPublicId || notice.pdfPublicId || \"\";\n      if (storagePath) {\n        await deleteUploadedAttachment(storagePath).catch((cleanupError) => console.warn(\"Attachment cleanup failed\", cleanupError));\n      }\n\n      toast(\"Notice delete ho gaya.\", \"success\");\n      await loadNotices();\n    }\n\n    async function publishNotice(event) {\n      event.preventDefault();\n      if (!(role === \"admin\" || role === \"superadmin\")) return;\n      const title = $(\"noticeTitle\").value.trim();\n      const message = $(\"noticeMessage\").value.trim();\n      const audience = $(\"audience\").value;\n      const file = $(\"noticeFile\").files[0] || null;\n      if (!title) return toast(\"Notice title required hai.\", \"error\");\n      if (!message && !file) return toast(\"Message likho ya PDF attach karo.\", \"error\");\n\n      publishBtn.disabled = true;\n      publishBtn.innerHTML = file\n        ? '<i class=\"fa-solid fa-spinner fa-spin\"></i>Uploading attachment...'\n        : '<i class=\"fa-solid fa-spinner fa-spin\"></i>Publishing...';\n      let upload = {};\n      try {\n        upload = await uploadAttachment(file);\n        publishBtn.innerHTML = '<i class=\"fa-solid fa-spinner fa-spin\"></i>Saving notice...';\n        await addDoc(collection(db, \"schools\", schoolId, \"notices\"), {\n          schoolId,\n          title,\n          message,\n          audience,\n          recipientRoles: audience === \"all\" ? [\"students\", \"teachers\", \"librarians\", \"accountants\"] : [audience],\n          attachmentUrl: upload.attachmentUrl || \"\",\n          attachmentName: upload.attachmentName || \"\",\n          attachmentType: upload.attachmentType || \"\",\n          attachmentPublicId: upload.attachmentPublicId || \"\",\n          attachmentStoragePath: upload.attachmentStoragePath || \"\",\n          pdfUrl: upload.pdfUrl || \"\",\n          pdfName: upload.pdfName || \"\",\n          pdfPublicId: upload.pdfPublicId || \"\",\n          createdAt: serverTimestamp(),\n          createdBy: currentUser?.uid || currentProfile?.id || \"\",\n          createdByEmail: currentUser?.email || currentProfile?.email || \"\",\n          status: \"published\"\n        });\n\n        try {\n          const notificationResult = await sendNoticeNotification(title, message, audience);\n          toast(notificationResult?.skipped ? \"Notice publish ho gaya.\" : \"Notice publish ho gaya aur app notification bhej di.\", \"success\");\n        } catch (notifyError) {\n          console.warn(\"Notice saved but notification failed\", notifyError);\n          toast(`Notice saved, lekin notification nahi gayi: ${notifyError.message}`, \"error\");\n        }\n\n        noticeForm.reset();\n        await loadNotices();\n      } catch (error) {\n        console.error(error);\n        if (upload.attachmentStoragePath) {\n          await deleteUploadedAttachment(upload.attachmentStoragePath).catch((cleanupError) => console.warn(\"Attachment cleanup failed\", cleanupError));\n        }\n        toast(error.message || \"Notice publish nahi ho paya.\", \"error\");\n      } finally {\n        publishBtn.disabled = false;\n        publishBtn.innerHTML = '<i class=\"fa-solid fa-paper-plane\"></i>Publish Notice';\n      }\n    }\n\n    async function bootWithProfile(user, profile) {\n      currentUser = user;\n      currentProfile = profile || {};\n      role = normalizeRole(currentProfile.role || currentProfile.loginAs);\n      schoolId = resolveSchoolId(currentProfile, user);\n      if (!schoolId) {\n        noticeList.innerHTML = '<div class=\"empty\">School profile nahi mila. Please login again.</div>';\n        return;\n      }\n      configureForRole();\n      await loadNotices();\n    }\n\n    noticeForm.addEventListener(\"submit\", publishNotice);\n    $(\"refreshBtn\").addEventListener(\"click\", () => loadNotices().catch((error) => toast(error.message, \"error\")));\n    noticeList.addEventListener(\"click\", (event) => {\n      const button = event.target.closest(\".notice-delete-btn\");\n      if (!button) return;\n      deleteNotice(button.dataset.noticeId).catch((error) => {\n        console.error(error);\n        toast(error.message || \"Notice delete nahi ho paya.\", \"error\");\n        loadNotices().catch((loadError) => console.warn(\"Notice reload failed\", loadError));\n      });\n    });\n\n    onAuthStateChanged(auth, async (user) => {\n      if (user) {\n        try {\n          const profile = await getProfile(user.uid);\n          await bootWithProfile(user, profile || { id: user.uid, role: \"admin\" });\n        } catch (error) {\n          console.error(error);\n          toast(\"Profile load nahi ho paya.\", \"error\");\n        }\n        return;\n      }\n\n      const session = getStudentSession();\n      if (session?.schoolId || session?.adminId) {\n        await bootWithProfile(null, { ...session, role: session.role || session.loginAs || \"student\" });\n        return;\n      }\n\n      window.location.replace(\"#/index.html\");\n    });\n  "},{"attributes":{"type":"module","src":"access-control.js"},"text":""},{"attributes":{"src":"schoolix-polish.js"},"text":""},{"attributes":{"src":"admin-shell.js?v=navbar-20260721"},"text":""}]};
